// The shape of a reading list item. Every episode's list lives in Laravel
// (generated by scripts/data/extras.mjs); articles carry their own. Sources
// are invented and have no links; only items on this site link anywhere.

export type SourceType = 'Book' | 'Article' | 'Report' | 'Data'

export interface ReadingItem {
  id?: string
  type: SourceType
  title: string
  /** Author, publisher or organisation. */
  source: string
  year: number
  /** When it came up, in seconds from the start of the show. */
  at?: number
  /** A route on this site, for sources the site published itself. */
  to?: string
}
